                if (f.IsArray) { return ArraySize(value, f, ref ids, elemCache); }
                if (f.Kind == 12 || f.Kind == 33) { return Count(value, f) * (f.Kind == 33 ? 2L : 1L); }
                return ElementSize(value, f, 0, ref ids, false);
            }
            static long ElementSize(object value, TableFieldInfo f, int i, ref Ids ids, bool framed)
            {
                if (f.Kind == 13)
                {
                    long n = BodySize(f.GetChild(value, i), f.Table, ref ids);
                    return n + (framed ? VarSize((ulong)n) : 0);
                }
                if (f.Kind == 15)
                {
                    object union = f.GetChild(value, i);
                    ulong tag = f.Arms.GetTag(union);
                    if (tag == 0) { return 1; }
                    TableUnionArmInfo arm = f.Arms.Arms[(int)tag];
                    long n = PayloadSize(union, arm.Field, ref ids);
                    return VarSize(ids.Reference(f.VariantId(tag))) + 1 + VarSize((ulong)n) + n;
                }
                if (f.Kind == 30)
                {
                    ulong v = f.GetRaw(value, i);
                    return VarSize(v == 0 ? 0 : ids.Reference(f.VariantId(v)));
                }
                if (f.Kind == 17) { return VarSize(ids.Graph.Index(f.GetChild(value, i))); }
                return Width(f.Kind);
            }
            static long ArraySize(object value, TableFieldInfo f, ref Ids ids, scoped Span<long> elemCache = default)
            {
                long n = 0; int count = 0;
                int total = Count(value, f);
                for (int i = 0; i < total; i++)
                {
                    if (f.KeyId != null)
                    {
                        if (DefaultElement(value, f, i)) { continue; }
                        long elem = ElementSize(value, f, i, ref ids, false);
                        n += VarSize(ids.Reference(f.KeyId((ulong)i + 1))) + VarSize((ulong)elem) + elem;
                    }
                    else if (f.Kind == 13)
                    {
                        long childBody = BodySize(f.GetChild(value, i), f.Table, ref ids);
                        if (!elemCache.IsEmpty && i < elemCache.Length) { elemCache[i] = childBody; }
                        n += VarSize((ulong)childBody) + childBody;
                    }
                    else { n += ElementSize(value, f, i, ref ids, true); }
                    count++;
                }
                return 1 + VarSize((ulong)count) + n;
            }
            static long BodySize(object value, TableTypeInfo type, ref Ids ids, scoped Span<long> rootPayloadSizes = default, scoped Span<long> rootElemSizes = default)
            {
                long n = 1;
                int elemOffset = 0;
                for (int i = 0; i < type.Fields.Length; i++)
                {
                    TableFieldInfo f = type.Fields[i];
                    if (!Rides(value, f)) { continue; }
                    n += VarSize(ids.Reference(f.Id)) + 1;
                    if (f.IsArray || f.Kind == 12 || f.Kind == 33 || f.Kind == 13)
                    {
                        scoped Span<long> elemCache = default;
                        if (f.IsArray && f.KeyId == null && f.Kind == 13 && !rootElemSizes.IsEmpty)
                        {
                            int c = Count(value, f);
                            int take = Math.Min(c, Math.Max(0, rootElemSizes.Length - elemOffset));
                            elemCache = rootElemSizes.Slice(elemOffset, take);
                            elemOffset += take;
                        }
                        long payload = PayloadSize(value, f, ref ids, elemCache);
                        n += VarSize((ulong)payload) + payload;
                        if (!rootPayloadSizes.IsEmpty) { rootPayloadSizes[i] = payload; }
                    }
                    else { n += ElementSize(value, f, 0, ref ids, true); }
                }
                return n;
            }
            static void WriteElement(ref Writer w, object value, TableFieldInfo f, int i, ref Ids ids, bool framed)
            {
                if (f.Kind == 13)
                {
                    object child = f.GetChild(value, i);
                    if (framed) { w.Var((ulong)BodySize(child, f.Table, ref ids)); }
                    WriteBody(ref w, child, f.Table, ref ids);
                }
                else if (f.Kind == 15)
                {
                    object union = f.GetChild(value, i); ulong tag = f.Arms.GetTag(union);
                    if (tag == 0) { w.Var(0); return; }
                    TableUnionArmInfo arm = f.Arms.Arms[(int)tag];
                    w.Var(ids.Reference(f.VariantId(tag))); w.Byte(arm.Field == null ? (byte)32 : Kind(arm.Field));
                    w.Var((ulong)PayloadSize(union, arm.Field, ref ids));
                    WritePayload(ref w, union, arm.Field, ref ids);
                }
                else if (f.Kind == 30)
                {
                    ulong v = f.GetRaw(value, i);
                    w.Var(v == 0 ? 0 : ids.Reference(f.VariantId(v)));
                }
                else if (f.Kind == 17) { w.Var(ids.Graph.Index(f.GetChild(value, i))); }
                else if (f.GetWide != null) {
                    UInt128 raw = f.GetWide(value, i); int width = Width(f.Kind);
                    w.Fixed((ulong)raw, Math.Min(width, 8)); if (width == 16) { w.Fixed((ulong)(raw >> 64), 8); }
                }
                else { w.Fixed(f.GetBuffer != null ? f.GetBuffer(value)[i] : f.GetRaw(value, i), Width(f.Kind)); }
            }
            static void WritePayload(ref Writer w, object value, TableFieldInfo f, ref Ids ids, scoped ReadOnlySpan<long> elemCache = default)
            {
                if (f == null) { return; }
                if (f.IsArray)
                {
                    w.Byte(f.Kind);
                    int total = Count(value, f);
                    int count = total;
                    if (f.KeyId != null)
                    {
                        count = 0;
                        for (int i = 0; i < f.ArrayBound; i++) { if (!DefaultElement(value, f, i)) { count++; } }
                    }
                    w.Var((ulong)count);
                    for (int i = 0; i < total; i++)
                    {
                        if (f.KeyId != null)
                        {
                            if (DefaultElement(value, f, i)) { continue; }
                            w.Var(ids.Reference(f.KeyId((ulong)i + 1)));
                            w.Var((ulong)ElementSize(value, f, i, ref ids, false));
                            WriteElement(ref w, value, f, i, ref ids, false);
                        }
                        else if (f.Kind == 13)
                        {
                            object child = f.GetChild(value, i);
                            long childBody = (!elemCache.IsEmpty && i < elemCache.Length) ? elemCache[i] : BodySize(child, f.Table, ref ids);
                            w.Var((ulong)childBody);
                            WriteBody(ref w, child, f.Table, ref ids);
                        }
                        else
                        {
                            WriteElement(ref w, value, f, i, ref ids, true);
                        }
                    }
                }
                else if (f.Kind == 33) { char[] chars = f.GetChars(value); int count = Count(value, f); for (int i = 0; i < count; i++) { w.Fixed(chars[i], 2); } }
                else if (f.Kind == 12) { w.Raw(f.GetBuffer(value).AsSpan(0, Count(value, f))); }
                else { WriteElement(ref w, value, f, 0, ref ids, false); }
            }
            static void WriteBody(ref Writer w, object value, TableTypeInfo type, ref Ids ids, bool root = false, scoped ReadOnlySpan<long> rootPayloadSizes = default, scoped ReadOnlySpan<long> rootElemSizes = default)
            {
                int elemOffset = 0;
                for (int i = 0; i < type.Fields.Length; i++)
                {
                    TableFieldInfo f = type.Fields[i];
                    if (!Rides(value, f)) { continue; }
                    w.Header(ids.Reference(f.Id), Kind(f));
                    scoped ReadOnlySpan<long> elemCache = default;
                    if (f.IsArray && f.KeyId == null && f.Kind == 13 && !rootElemSizes.IsEmpty)
                    {
                        int c = Count(value, f);
                        int take = Math.Min(c, Math.Max(0, rootElemSizes.Length - elemOffset));
                        elemCache = rootElemSizes.Slice(elemOffset, take);
                        elemOffset += take;
                    }
                    if (f.IsArray || f.Kind == 12 || f.Kind == 33 || f.Kind == 13)
                    { w.Var((ulong)(rootPayloadSizes.IsEmpty ? PayloadSize(value, f, ref ids) : rootPayloadSizes[i])); }
                    WritePayload(ref w, value, f, ref ids, elemCache);
                }
                if (root) { WriteNodes(ref w, ref ids); }
                w.Var(0);
            }
            public static bool CollectField(object value, TableFieldInfo f, ref Ids ids)
            {
                if (f.WireGuard != null && !f.WireGuard(value)) { return true; }
                if (f.Optional && !f.GetPresent(value)) { return true; }
                if (f.Counted && (Count(value, f) < 0 || Count(value, f) > f.ArrayBound)) { return false; }
                return !Rides(value, f) || (ids.Add(f.Id) && CollectPayload(value, f, ref ids));
            }
            public static long BodySizeField(object value, TableFieldInfo f, ref Ids ids, scoped Span<long> elemCache, out long payload)
            {
                payload = 0;
                if (!Rides(value, f)) { return 0; }
                long n = VarSize(ids.Reference(f.Id)) + 1;
                if (f.IsArray || f.Kind == 12 || f.Kind == 33 || f.Kind == 13)
                {
                    payload = PayloadSize(value, f, ref ids, elemCache);
                    n += VarSize((ulong)payload) + payload;
                }
                else
                {
                    n += ElementSize(value, f, 0, ref ids, true);
                }
                return n;
            }
            public static long BodySizeField(object value, TableFieldInfo f, ref Ids ids, scoped Span<long> elemCache = default)
            {
                return BodySizeField(value, f, ref ids, elemCache, out _);
            }
            public static void WriteBodyField(ref Writer w, object value, TableFieldInfo f, ref Ids ids, scoped ReadOnlySpan<long> elemCache = default, long cachedPayload = -1)
            {
                if (!Rides(value, f)) { return; }
                w.Header(ids.Reference(f.Id), Kind(f));
                if (f.IsArray || f.Kind == 12 || f.Kind == 33 || f.Kind == 13)
                {
                    long payload = cachedPayload >= 0 ? cachedPayload : PayloadSize(value, f, ref ids);
                    w.Var((ulong)payload);
                }
                WritePayload(ref w, value, f, ref ids, elemCache);
            }
            public static long Save(object value, TableTypeInfo type, Span<byte> buffer, Span<ulong> vocabulary, bool measure)
            {
                // Preserve first-use vocabulary order; the index only accelerates
                // references during the repeated collect, measure and write walks.
                // Bound extra stack use for large schemas; their existing linear
                // path remains available without a per-save heap allocation.
                int slots = 0;
                if (vocabulary.Length <= 1024)
                {
                    slots = 1;
                    while (slots < vocabulary.Length * 2) { slots <<= 1; }
                }
                Span<int> index = stackalloc int[slots];
                Span<uint> ordinalSlots = vocabulary.Length <= 1024 ? stackalloc uint[vocabulary.Length] : default;
                Span<int> ordinalOf = vocabulary.Length <= 1024 ? stackalloc int[vocabulary.Length] : default;
                Ids ids = new Ids(vocabulary, index, ordinalSlots, ordinalOf);
                if (type.Variable) { ids.Graph = Number(value, type); if (ids.Graph == null) { return -1; } }
                if (!Collect(value, type, ref ids) || !CollectNodes(ref ids)) { return -1; }
                // Reuse the root's measured length prefixes while writing its fields,
                // and cache immediate child element body sizes for root unkeyed table arrays.
                // These ceilings bound additional stack storage to 2 KiB each (4 KiB total).
                // Roots with >256 fields bypass root payload sizing caching while element
                // caching remains active; element counts beyond 256 keep their cached prefix
                // with remaining elements falling back to on-demand sizing; variable graphs
                // and Measure retain the uncached path. Nested writes keep their own sizing
                // path, so no recursive cache or shared state lives across calls, and all
                // validation still precedes the first output byte.
                int cachedFields = !measure && !type.Variable && type.Fields.Length <= 256 ? type.Fields.Length : 0;
                Span<long> rootPayloadSizes = stackalloc long[cachedFields];
                int cachedElemSlots = !measure && !type.Variable ? type.RootElemSlots : 0;
                Span<long> rootElemSizes = stackalloc long[cachedElemSlots];
                long n = 1 + BodySize(value, type, ref ids, rootPayloadSizes, rootElemSizes) + 8L * ids.Count + 8;
                long nodes = NodesSize(ref ids);
                if (nodes != 0) { n += VarSize(ids.Reference(ulong.MaxValue)) + 1 + VarSize((ulong)nodes) + nodes; }
                if (measure) { return n; }
                if (n > buffer.Length) { return -1; }
                scoped Writer w = new Writer(buffer);
                w.Byte(1); WriteBody(ref w, value, type, ref ids, true, rootPayloadSizes, rootElemSizes);
                for (int i = 0; i < ids.Count; i++) { w.Fixed(ids.Values[i], 8); }
                w.Fixed((ulong)ids.Count, 8);
                return w.Offset;
            }

            static bool Widen(byte from, byte to)
            {
                return (from >= 2 && to <= 5 && from < to) || (from >= 6 && to <= 9 && from < to) || (from == 10 && to == 11) || (to == 18 && from >= 2 && from <= 5) || (to == 19 && from >= 6 && from <= 9);
            }
            // Numeric float conversion quiets signalling NaNs. Carry their sign and
            // payload by bits; ordinary finite values use the exact hardware widening.
            static ulong WidenFloat(uint raw)
            {
                if ((raw & 0x7f800000u) == 0x7f800000u)
                { return ((ulong)(raw & 0x80000000u) << 32) | 0x7ff0000000000000ul | ((ulong)(raw & 0x7fffffu) << 29); }
                return TableDoubleToBits((double)TableBitsToFloat(raw));
            }
            static bool Compatible(byte from, byte to, TableReport report)
            {
                if (from == to) { return true; }
                if (Widen(from, to)) { report.Widened++; return true; }
                report.KindMismatch++; return false;
            }
            static bool Damage(TableReport report) { report.Malformed = true; return false; }
            static bool EndsEarly(Reader r)
            {
                while (r.Ref(out ulong reference, out _))
                {
                    if (reference == 0) { return r.Offset != r.Buffer.Length; }
                    if (!r.Has(1) || !r.Skip(r.Byte())) { return false; }
                }
                return false;
            }
            static int FindVariant(TableFieldInfo f, ulong id, bool key)
            {
                int max = key ? f.ArrayBound : (int)f.EnumMax;
                for (int i = 1; i <= max; i++)
                {
                    if (Named(key ? f.KeyName((ulong)i) : f.EnumName((ulong)i)) &&
                        (key ? f.KeyId((ulong)i) : f.VariantId((ulong)i)) == id) { return i; }
                }
                return 0;
            }
            static bool ReadScalar(ref Reader r, object value, TableFieldInfo f, int index, byte kind, TableReport report)
            {
                if (f.GetWide != null)
                {
                    int width = Width(kind);
                    if (!r.Has(width)) { return Damage(report); }
                    UInt128 wide = r.Fixed(Math.Min(width, 8));
                    if (width == 16) { wide |= (UInt128)r.Fixed(8) << 64; }
                    else if ((kind >= 2 && kind <= 5) || (kind >= 20 && kind <= 23))
                    { int shift = 128 - width * 8; wide = unchecked((UInt128)((Int128)(wide << shift) >> shift)); }
                    if (f.ClampWide != null) { wide = f.ClampWide(wide, report); }
                    f.SetWide(value, index, wide); return true;
                }
                ulong raw;
                if (kind == 30)
                {
                    if (!r.Ref(out ulong reference, out ulong id)) { return Damage(report); }
                    int variant = reference == 0 ? 0 : FindVariant(f, id, false);
                    if (reference != 0 && variant == 0) { report.Unknown++; }
                    raw = (ulong)variant;
                }
                else
                {
                    int width = Width(kind);
                    if (!r.Has(width)) { return Damage(report); }
                    raw = r.Fixed(width);
                    if (kind >= 2 && kind <= 5 && width < 8)
                    { int shift = 64 - width * 8; raw = unchecked((ulong)((long)(raw << shift) >> shift)); }
                    if (kind == 1) { raw = raw == 0 ? 0ul : 1ul; }
                    if (kind == 10 && f.Kind == 11) { raw = WidenFloat((uint)raw); }
                    if (f.ClampRaw != null) { raw = f.ClampRaw(raw, report); }
                }
                if (f.GetBuffer != null) { f.GetBuffer(value)[index] = (byte)raw; }
                else { f.SetRaw(value, index, raw); }
                return true;
            }
            static bool ReadElement(ref Reader r, object value, TableFieldInfo f, int index, byte kind, TableReport report, bool framed)
            {
                if (kind == 17)
                {
                    if (!r.Var(out ulong indexValue)) { return Damage(report); }
                    f.SetChild(value, index, r.Graph == null ? null : r.Graph.Resolve(indexValue, f, report)); return true;
                }
                if (kind == 13)
                {
                    Reader sub = r;
                    if (framed && !r.Slice(out sub)) { return Damage(report); }
                    object child = f.GetChild(value, index);
                    ReadBody(ref sub, child, f.Table, report, true);
                    if (sub.Offset != sub.Buffer.Length) { f.Table.Reset(child); Damage(report); }
                    if (!framed) { r.Offset = r.Buffer.Length; }
                    return true;
                }
                if (kind == 15)
                {
                    if (!r.Var(out ulong reference)) { return Damage(report); }
                    object union = f.GetChild(value, index);
                    // Array elements establish None as soon as their reference is
                    // present, even if its index or the following arm header is bad.
                    // A scalar union field retains its old selection until the whole
                    // header is bounded, matching the C++ reader under repeated fields.
                    if (f.IsArray) { f.Arms.SetTag(union, 0); }
                    if (reference == 0) { f.Arms.SetTag(union, 0); return true; }
                    if (reference > (ulong)r.Vocabulary.Length / 8) { return Damage(report); }
                    ulong id = Read64(r.Vocabulary, ((int)reference - 1) * 8);
                    if (!r.Has(1)) { return Damage(report); }
                    byte armKind = r.Byte();
                    if (!r.Slice(out Reader arm)) { return Damage(report); }
                    f.Arms.SetTag(union, 0);
                    int tag = FindVariant(f, id, false);
                    if (tag == 0) { report.Unknown++; return true; }
                    TableUnionArmInfo info = f.Arms.Arms[tag];
                    byte expected = info.Field == null ? (byte)32 : Kind(info.Field);
                    // A widening arm must first have exactly the source kind's width.
                    // Damaged framing never records a successful widening event.
                    if (Widen(armKind, expected) && arm.Buffer.Length != Width(armKind))
                    { Damage(report); return true; }
                    if (!Compatible(armKind, expected, report)) { return true; }
                    f.Arms.SetTag(union, (ulong)tag);
                    if (!ReadArm(ref arm, union, info.Field, armKind, report)) { f.Arms.SetTag(union, 0); }
                    return true;
                }
                return ReadScalar(ref r, value, f, index, kind, report);
            }
            // Selection establishes storage. Table bodies take their declared defaults;
            // general arms are zeroed, including unused tails of arrays of plain types.
            internal static void ResetArm(object value, TableFieldInfo f)
            {
                if (f.Kind == 13 && !f.IsArray) { f.Table.Reset(f.GetChild(value, 0)); }
                else { ZeroField(value, f); }
            }
            static void ZeroField(object value, TableFieldInfo f)
            {
                if (f.Dynamic) { f.ResetField(value); return; }
                if (f.GetChars != null) { Array.Clear(f.GetChars(value), 0, f.ArrayBound); }
                else if (f.GetBuffer != null) { Array.Clear(f.GetBuffer(value), 0, f.ArrayBound); }
                else
                {
                    int n = f.IsArray ? f.ArrayBound : 1;
                    for (int i = 0; i < n; i++)
                    {
                        if (f.Kind == 13)
                        {
                            object child = f.GetChild(value, i);
                            foreach (TableFieldInfo field in f.Table.Fields) { ZeroField(child, field); }
                        }
                        else if (f.Kind == 15) { ResetUnion(f.GetChild(value, i), f.Arms); }
                        else if (f.Kind == 17) { f.SetChild(value, i, null); }
                        else if (f.SetWide != null) { f.SetWide(value, i, 0); }
                        else { f.SetRaw(value, i, 0); }
                    }
                }
                if (f.Counted) { f.SetCount(value, 0); }
                if (f.Optional) { f.SetPresent(value, false); }
            }
            // A shorter replacement, including a damaged one, must restore slots above
            // the new count to the value-initialized element (#725).
            static void ResetUnion(object union, TableUnionInfo arms)
            {
                if (union == null || arms == null) { return; }
                arms.SetTag(union, 0);
                if (arms.Arms == null) { return; }
                // C++ assigns a fresh element; C memsets. Tag-only leaves the previous
                // arm's storage (a list under None). Reset every payload arm.
                for (int a = 1; a < arms.Arms.Length; a++)
                {
                    TableFieldInfo payload = arms.Arms[a].Field;
                    if (payload != null) { ResetArm(union, payload); }
                }
            }
            static void ResetElement(object value, TableFieldInfo f, int i)
            {
                if (f.Kind == 13 && f.Table != null) { object child = f.GetChild(value, i); if (child != null) { f.Table.Reset(child); } }
                else if (f.Kind == 15 && f.Arms != null) { ResetUnion(f.GetChild(value, i), f.Arms); }
                else if (f.Kind == 17) { f.SetChild(value, i, null); }
                else if (f.SetWide != null) { f.SetWide(value, i, 0); }
                else if (f.SetRaw != null) { f.SetRaw(value, i, f.DefaultRaw); }
            }
            static void ResetCountedTail(object value, TableFieldInfo f, int previous, int decoded)
            {
                if (value == null || f.SetCount == null) { return; }
                int end = previous;
                if (end > f.ArrayBound) { end = f.ArrayBound; }
                for (int i = decoded; i < end; i++) { ResetElement(value, f, i); }
                f.SetCount(value, decoded);
            }
            static bool ReadArm(ref Reader r, object value, TableFieldInfo f, byte kind, TableReport report)
            {
                if (f == null) { return r.Buffer.Length == 0 || Damage(report); }
                if (f.Map) { return ReadMapBody(ref r, value, f, report); }
                int width = Width(kind);
                if (width != 0 && r.Buffer.Length != width) { return Damage(report); }
                if (kind == 13)
                {
                    ReadBody(ref r, f.GetChild(value, 0), f.Table, report, true);
                    return r.Offset == r.Buffer.Length || Damage(report);
                }
                if (kind == 15) { return ReadElement(ref r, value, f, 0, kind, report, true); }
                if (kind == 17)
                {
                    if (!r.Var(out ulong indexValue) || r.Offset != r.Buffer.Length) { return Damage(report); }
                    f.SetChild(value, 0, r.Graph == null ? null : r.Graph.Resolve(indexValue, f, report));
                    return true;
                }
                if (kind == 12 || kind == 33)
                {
                    ResetArm(value, f);
                    return kind == 33 ? ReadChars(r.Buffer, value, f, report) : ReadText(r.Buffer, value, f, report);
                }
                if (kind == 14)
                {
                    ResetArm(value, f);
                    if (!r.Has(2)) { return true; } // an inert short arm still selects
                    byte elementKind = r.Byte();
                    if (!r.Var(out ulong count)) { return Damage(report); }
                    if (!Compatible(elementKind, f.Kind, report)) { return false; }
                    int keep = (int)Math.Min(count, (ulong)f.ArrayBound);
                    if (!f.Dynamic && count > (ulong)f.ArrayBound) { report.Clamped++; }
                    int decoded = 0;
                    for (int i = 0; i < keep; i++)
                    {
                        if (f.Dynamic) { if (!r.Has(1)) { Damage(report); break; } f.EnsureCount(value, i + 1); }
                        if (!ReadElement(ref r, value, f, i, elementKind, report, true)) { break; }
                        decoded++;
                    }
                    if (f.Counted) { f.SetCount(value, decoded); }
                    return true; // damaged elements preserve the selected arm's prefix
                }
                if (!ReadScalar(ref r, value, f, 0, kind, report)) { return false; }
                return r.Offset == r.Buffer.Length || Damage(report);
            }
            static bool ReadText(ReadOnlySpan<byte> text, object value, TableFieldInfo f, TableReport report)
            {
                if (!TextValid(text)) { return Damage(report); }
                int keep = text.Length;
                if (keep > f.ArrayBound)
                {
                    keep = f.ArrayBound; report.Clamped++;
                    while (keep > 0 && (text[keep] & 0xc0) == 0x80) { keep--; }
                }
                if(value!=null) { text.Slice(0,keep).CopyTo(f.GetBuffer(value)); f.SetCount(value,keep); }
                return true;
            }
            static bool ReadChars(ReadOnlySpan<byte> text, object value, TableFieldInfo f, TableReport report)
            {
                if ((text.Length & 1) != 0) { return Damage(report); }
                for (int i = 0; i < text.Length; i += 2)
                {
                    int c = text[i] | text[i + 1] << 8;
                    if (c == 0 || (c >= 0xdc00 && c <= 0xdfff)) { return Damage(report); }
                    if (c >= 0xd800 && c <= 0xdbff)
                    {
                        if (i + 3 >= text.Length) { return Damage(report); }
                        int low = text[i + 2] | text[i + 3] << 8;
                        if (low < 0xdc00 || low > 0xdfff) { return Damage(report); }
                        i += 2;
                    }
                }
                int keep = text.Length / 2;
                if (keep > f.ArrayBound)
                {
                    keep = f.ArrayBound; report.Clamped++;
                    if (keep > 0 && (text[keep * 2 - 1] & 0xfc) == 0xd8) { keep--; }
                }
                char[] storage = f.GetChars(value);
                for (int i = 0; i < keep; i++) { storage[i] = (char)(text[i * 2] | text[i * 2 + 1] << 8); }
                f.SetCount(value, keep); return true;
            }
            internal static bool TextValid(ReadOnlySpan<byte> text)
            {
                for (int i = 0; i < text.Length;)
                {
                    byte c = text[i++];
                    if (c == 0) { return false; }
                    if (c < 128) { continue; }
                    int n; uint v, min;
                    if (c >= 0xc2 && c <= 0xdf) { n = 1; v = (uint)(c & 31); min = 0x80; }
                    else if (c >= 0xe0 && c <= 0xef) { n = 2; v = (uint)(c & 15); min = 0x800; }
                    else if (c >= 0xf0 && c <= 0xf4) { n = 3; v = (uint)(c & 7); min = 0x10000; }
                    else { return false; }
                    if (n > text.Length - i) { return false; }
                    for (int j = 0; j < n; j++)
                    { byte b = text[i++]; if ((b & 0xc0) != 0x80) { return false; } v = (v << 6) | (uint)(b & 63); }
                    if (v < min || v > 0x10ffff || (v >= 0xd800 && v <= 0xdfff)) { return false; }
                }
                return true;
            }
            static bool ReadField(ref Reader r, object value, TableFieldInfo f, byte kind, TableReport report, out bool placed)
            {
                placed = true;
                if (f.Map) { if (!r.Slice(out Reader map)) { return Damage(report); } return ReadMapBody(ref map, value, f, report, r.Buffer.Slice(r.Offset - map.Buffer.Length)); }
                if (kind == 12 || kind == 33)
                {
                    if (!r.Slice(out Reader text)) { return Damage(report); }
                    if (!(kind == 33 ? ReadChars(text.Buffer, value, f, report) : ReadText(text.Buffer, value, f, report)))
                    { f.ResetField(value); }
                    return true;
                }
                if (kind == 14 || kind == 16)
                {
                    if (!r.Slice(out Reader array)) { return Damage(report); }
                    if (array.Buffer.Length < 2) { return true; } // inert, including under a repeat
                    byte elementKind = array.Byte();
                    // Match the reference's header cursor: the count is read at the
                    // enclosing cursor, then all elements are bounded by the array's L.
                    // A count spilling past L can clamp, but cannot invent an element.
                    Reader header = new Reader(r.Buffer.Slice(r.Offset - array.Buffer.Length + 1), r.Vocabulary);
                    if (!header.Var(out ulong count)) { Damage(report); return true; }
                    array.Offset = Math.Min(array.Buffer.Length, 1 + header.Offset);
                    if (!Compatible(elementKind, f.Kind, report)) { placed = false; return true; }
                    if (kind == 16)
                    {
                        for (ulong i = 0; i < count; i++)
                        {
                            if (!array.Ref(out ulong reference, out ulong id) || reference == 0 || !array.Slice(out Reader element))
                            { Damage(report); break; }
                            int slot = FindVariant(f, id, true);
                            if (slot == 0) { report.Unknown++; continue; }
                            ReadElement(ref element, value, f, slot - 1, elementKind, report, false);
                        }
                    }
                    else
                    {
                        int keep = (int)Math.Min(count, (ulong)f.ArrayBound);
                        if (!f.Dynamic && count > (ulong)f.ArrayBound) { report.Clamped++; }
                        int previous = f.Counted && f.GetCount != null ? f.GetCount(value) : 0;
                        int decoded = 0;
                        for (int i = 0; i < keep; i++)
                        {
                            if (f.Dynamic) { if (!array.Has(1)) { Damage(report); break; } f.EnsureCount(value, i + 1); }
                            if (!ReadElement(ref array, value, f, i, elementKind, report, true)) { break; }
                            decoded++;
                        }
                        if (f.Counted) { ResetCountedTail(value, f, previous, decoded); }
                    }
                    return true;
                }
                return ReadElement(ref r, value, f, 0, kind, report, true);
            }
            // IndexFields builds a power-of-two open-addressing table over Fields using
            // the same mix as Ids.Slot. Nested static TableType() Build() calls it
            // before publishing Instance, so ARM64 sees the index with the descriptor.
            internal static void IndexFields(TableTypeInfo type)
            {
                TableFieldInfo[] fields = type.Fields;
                if (fields == null || fields.Length == 0)
                {
                    type.IdIndex = Array.Empty<TableFieldInfo>();
                    type.IdMask = 0;
                    return;
                }
                int slots = 1;
                while (slots < fields.Length * 2) { slots <<= 1; }
                TableFieldInfo[] index = new TableFieldInfo[slots];
                int mask = slots - 1;
                for (int i = 0; i < fields.Length; i++)
                {
                    TableFieldInfo f = fields[i];
                    int slot = unchecked((int)(f.Id ^ (f.Id >> 32))) & mask;
                    while (index[slot] != null) { slot = (slot + 1) & mask; }
                    index[slot] = f;
                }
                type.IdIndex = index;
                type.IdMask = mask;
            }
            internal static TableFieldInfo FindField(TableTypeInfo type, ulong id)
            {
                TableFieldInfo[] index = type.IdIndex;
                if (index != null)
                {
                    if (index.Length == 0) { return null; }
                    int mask = type.IdMask;
                    int slot = unchecked((int)(id ^ (id >> 32))) & mask;
                    for (;;)
                    {
                        TableFieldInfo f = index[slot];
                        if (f == null) { return null; }
                        if (f.Id == id) { return f; }
                        slot = (slot + 1) & mask;
                    }
                }
                if (type.Fields == null) { return null; }
                foreach (TableFieldInfo f in type.Fields) { if (f.Id == id) { return f; } }
                return null;
            }
            static bool ReadBody(ref Reader r, object value, TableTypeInfo type, TableReport report, bool nested)
            {
                // Load resets the root before even the framing checks. Every nested
                // occurrence still replaces its target, including repeated fields.
                if (nested) { type.Reset(value); }
                for (;;)
                {
                    if (!r.Ref(out ulong reference, out ulong id)) { return Damage(report); }
                    if (reference == 0) { return true; }
                    if ((nested && id == ulong.MaxValue) || id == ulong.MaxValue - 1 || id == ulong.MaxValue - 2) { return Damage(report); }
                    if (!r.Has(1)) { return Damage(report); }
                    byte kind = r.Byte();
                    TableFieldInfo field = FindField(type, id);
                    if (!nested && id == ulong.MaxValue && type.Variable)
                    { if (!r.Skip(kind)) { return Damage(report); } continue; }
                    if (field == null)
                    {
                        report.Unknown++;
                        if (!r.Skip(kind)) { return Damage(report); }
                        continue;
                    }
                    int beforeWidened = report.Widened;
                    if (Widen(kind,Kind(field)) && !r.Has(Width(kind))) { return Damage(report); }
                    if (!Compatible(kind, Kind(field), report))
                    {
                        if (!r.Skip(kind)) { return Damage(report); }
                        continue;
                    }
                    if (field.MapKey) { report.Widened = beforeWidened; }
                    if (!ReadField(ref r, value, field, kind, report, out bool placed)) { return false; }
                    if (field.Optional && placed) { field.SetPresent(value, true); }
                }
            }
            static bool DistinctVocabulary(ReadOnlySpan<byte> vocabulary)
            {
                int count = vocabulary.Length / 8;
                if (count >= 16 && count <= 256)
                {
                    // One KiB, independent of the input's claimed count. Slots store
                    // ordinal+1, so the identity zero remains an ordinary identity.
                    // At most 256 entries occupy 512 slots: even deliberately colliding
                    // identities reach an empty slot after at most 256 occupied probes.
                    Span<ushort> slots = stackalloc ushort[512];
                    slots.Clear();
                    for (int i = 0; i < count; i++)
                    {
                        ulong id = Read64(vocabulary, i * 8);
                        int slot = (int)(unchecked(id * 0x9e3779b97f4a7c15ul) >> 55);
                        while (slots[slot] != 0)
                        {
                            if (id == Read64(vocabulary, (slots[slot] - 1) * 8)) { return false; }
                            slot = (slot + 1) & 511;
                        }
                        slots[slot] = (ushort)(i + 1);
                    }
                    return true;
                }
                // Tiny vocabularies avoid scratch initialization. Larger foreign
                // vocabularies keep the existing allocation-free validation path.
                for (int i = 0; i < vocabulary.Length; i += 8)
                {
                    ulong id = Read64(vocabulary, i);
                    for (int j = 0; j < i; j += 8)
                    { if (id == Read64(vocabulary, j)) { return false; } }
                }
                return true;
            }
            static Verdict Finish(TableReport report, Verdict verdict) { report.Verdict = verdict; return verdict; }
            public static Verdict Load(object value, TableTypeInfo type, ReadOnlySpan<byte> bytes, TableReport report)
            {
                if (report == null) { report = new TableReport(); }
                type.Reset(value);
                report.Refused = false; report.Reason = null;
                if (bytes.Length == 0) { Damage(report); return Finish(report, Verdict.Damaged); }
                if (bytes[0] != 1)
                {
                    report.Refused = true;
                    report.Reason = bytes[0] == 2 ? "message_form_as_file" : "newer_form";
                    return Finish(report, Verdict.Refused);
                }
                if (bytes.Length < 9) { Damage(report); return Finish(report, Verdict.Damaged); }
                ulong count = Read64(bytes, bytes.Length - 8);
                if (count > (ulong)(bytes.Length - 9) / 8) { Damage(report); return Finish(report, Verdict.Damaged); }
                int end = bytes.Length - 8 - (int)count * 8;
                ReadOnlySpan<byte> vocabulary = bytes.Slice(end, (int)count * 8);
                if (!DistinctVocabulary(vocabulary)) { Damage(report); return Finish(report, Verdict.Damaged); }
                Reader r = new Reader(bytes.Slice(1, end - 1), vocabulary);
                if (EndsEarly(r)) { Damage(report); return Finish(report, Verdict.Damaged); }
                if (type.Variable) { if (LoadMeasure(type, bytes, out _) < 0) { Damage(report); return Finish(report, Verdict.Damaged); } r.Graph = ReadGraph(r, value, type, report); }
                return Finish(report, ReadBody(ref r, value, type, report, false) ? Verdict.Ok : Verdict.BodyStopped);
            }
        }
        // ---- form-1 table wire: end ----

            public static class TableFixedWire
            {
                public const byte Form = 3;
                public const int HeaderBytes = 16;
                public const int HashAt = 8;
                public const uint NoGuard = 0xFFFFFFFFu;
                public const int MaxDepth = 32;
                public const uint RecordMaxBytes = 65536;

                // The opcodes for plan entries
                public const byte Copy = 0;    // move Size bytes
                public const byte Count = 1;   // a count: clamp to reader's bound
                public const byte Text = 2;    // a length, then units, then copy
                public const byte Ordinal = 3; // a variant ordinal, remapped through plan table
                public const byte Widen = 4;   // narrower source into wider destination
                public const byte Const = 5;   // constant value: e.g. remapped union tag
                public const byte WidenF = 6;  // float32 into float64
                public const byte Flat = 7;    // folded flat array copy
                // A FOLDED RUN WHOSE TWO IMAGES DIFFER IN WIDTH (§5.2 EMIT kind 14, and
                // §6's flat-element fold). The fold's premise is that the element's
                // STORAGE image IS its WIRE image, and a widening breaks that premise: the
                // writer's run is narrower than the reader's storage, element for element.
                // §5.2's EMIT has no fold at all — it emits the element min(their_n, my_n)
                // times — and a FOLDED destination has no element-wise slot to aim those
                // entries at, so the widening happens inside ONE entry here. Sign is 0 for
                // a zero-extend, 1 for a sign-extend and 2 for f32 into f64; Meta is the
                // WRITER's element width and DstSize the READER's.
                public const byte FlatWiden = 8;

                // Arg on a Text entry
                public const byte TextUtf8 = 1;
                public const byte TextWide = 2;
                public const byte TextBytes = 3;

                public const int EntryBytes = 17;

                public static bool Widens(byte from, byte to)
                {
                    if (from >= 6 && from <= 9 && to >= 6 && to <= 9) { return to > from; }
                    if (from >= 2 && from <= 5 && to >= 2 && to <= 5) { return to > from; }
                    // THE FIXED-POINT RUNGS, signed 20..24 and unsigned 25..29: a
                    // fixed(I,F) into a wider I at equal F is a LADDER widen and not a
                    // kind that moved (docs/FIXED-FORM-ALGORITHM.md §1, §5.1).
                    if (from >= 20 && from <= 24 && to >= 20 && to <= 24) { return to > from; }
                    if (from >= 25 && from <= 29 && to >= 25 && to <= 29) { return to > from; }
                    return from == 10 && to == 11;
                }

                // A WIDEN'S SIGN IS THE LADDER'S: the source sign-extends when the
                // WRITER's kind is signed — i8..i64 and a SIGNED fixed(I,F), 20..24 —
                // and zero-extends otherwise (§5.2). The SAME-KIND widen has no sign at
                // all and the grown enum ordinal none either: taken as stated, not
                // inferred from the kind's signedness.
                public static bool SignedKind(byte kind)
                {
                    return (kind >= 2 && kind <= 5) || (kind >= 20 && kind <= 24);
                }

                public static ulong HashOf(ReadOnlySpan<byte> layout)
                {
                    ulong h = 0xcbf29ce484222325ul;
                    for (int i = 0; i < layout.Length; ++i)
                    {
                        h ^= (ulong)layout[i];
                        h *= 0x100000001b3ul;
                    }
                    return h;
                }

                public static TableFixedLayoutEntry EntryAt(TableFixedLayoutView b, int i)
                {
                    ReadOnlySpan<byte> e = b.Bytes.Slice(4 + i * EntryBytes, EntryBytes);
                    TableFixedLayoutEntry outEntry = default;
                    outEntry.Id = BinaryPrimitives.ReadUInt64LittleEndian(e);
                    outEntry.Kind = e[8];
                    outEntry.Size = BinaryPrimitives.ReadUInt32LittleEndian(e.Slice(9));
                    outEntry.Children = BinaryPrimitives.ReadUInt32LittleEndian(e.Slice(13));
                    return outEntry;
                }

                public static int Subtree(TableFixedLayoutView b, int i)
                {
                    if (i < 0 || i >= b.Count) { return 1; }
                    TableFixedLayoutEntry e = EntryAt(b, i);
                    int n = 1;
                    int at = i + 1;
                    for (uint c = 0; c < e.Children; ++c)
                    {
                        if (at >= b.Count) { break; }
                        int sub = Subtree(b, at);
                        at += sub;
                        n += sub;
                    }
                    return n;
                }

                public static uint UnionArmBytes(TableFixedLayoutView b, int i)
                {
                    TableFixedLayoutEntry e = EntryAt(b, i);
                    uint widest = 0;
                    int at = i + 1;
                    for (uint k = 0; k < e.Children; ++k)
                    {
                        TableFixedLayoutEntry a = EntryAt(b, at);
                        if (a.Size > widest) { widest = a.Size; }
                        at += Subtree(b, at);
                    }
                    return widest;
                }

                public static uint TagBytes(TableFixedLayoutView b, int i)
                {
                    return EntryAt(b, i).Size - UnionArmBytes(b, i);
                }

                private static bool LeafSize(byte kind, uint size, out bool isLeaf)
                {
                    isLeaf = true;
                    switch (kind)
                    {
                        case 1:  return size == 1;                 // bool
                        case 2:  return size == 1;                 // i8
                        case 3:  return size == 2;                 // i16
                        case 4:  return size == 4;                 // i32
                        case 5:  return size == 8;                 // i64
                        case 6:  return size == 1 || size == 4;    // u8, and bits(1..8)
                        case 7:  return size == 2 || size == 4;    // u16, and bits(9..16)
                        case 8:  return size == 4;                 // u32, and bits(17..32)
                        case 9:  return size == 8;                 // u64, flags, and bits(33..64)
                        case 10: return size == 4;                 // f32
                        case 11: return size == 8;                 // f64
                        case 17: return size == 4;                 // pointer index
                        case 18: case 19: return size == 16;       // i128, u128
                        case 20: case 25: return size == 1;        // fixed8, ufixed8
                        case 21: case 26: return size == 2;
                        case 22: case 27: return size == 4;
                        case 23: case 28: return size == 8;
                        case 24: case 29: return size == 16;
                        case 32: return size == 0;                 // variant arm that holds nothing
                    }
                    isLeaf = false;
                    return true;
                }

                private static bool OrdinalWidth(uint n) => n == 1 || n == 2 || n == 4 || n == 8;

                private static bool KnownKind(byte kind)
                {
                    if (kind >= 1 && kind <= 30) return true;
                    return kind == 32 || kind == 33 || kind == 35;
                }

                private ref struct Checker
                {
                    public TableFixedLayoutView Layout;
                    public string Why;
                    public bool Bad;

                    public void Fail(string why)
                    {
                        if (!Bad)
                        {
                            Bad = true;
                            Why = why;
                        }
                    }
                }

                private static int CheckEntry(ref Checker c, int i, int depth)
                {
                    if (c.Bad) return 0;
                    if (i < 0 || i >= c.Layout.Count) { c.Fail("layout_tree_unclosed"); return 0; }
                    if (depth > MaxDepth) { c.Fail("layout_too_deep"); return 0; }
                    TableFixedLayoutEntry e = EntryAt(c.Layout, i);
                    if (!KnownKind(e.Kind)) { c.Fail("layout_kind_unknown"); return 0; }
                    if (e.Size > RecordMaxBytes) { c.Fail("layout_record_too_large"); return 0; }

                    int at = i + 1;
                    ulong sum = 0;
                    uint widest = 0;
                    uint firstSize = 0, secondSize = 0;
                    byte firstKind = 0;
                    uint firstChildren = 0;
                    bool kidsAreVariants = true;
                    for (uint k = 0; k < e.Children; ++k)
                    {
                        int child = at;
                        int used = CheckEntry(ref c, child, depth + 1);
                        if (c.Bad) return 0;
                        TableFixedLayoutEntry ce = EntryAt(c.Layout, child);
                        if (k == 0) { firstSize = ce.Size; firstKind = ce.Kind; firstChildren = ce.Children; }
                        if (k == 1) { secondSize = ce.Size; }
                        if (ce.Kind != 32) { kidsAreVariants = false; }
                        sum += ce.Size;
                        if (ce.Size > widest) { widest = ce.Size; }
                        if (sum > RecordMaxBytes) { c.Fail("layout_record_too_large"); return 0; }
                        at += used;
                    }

                    if (!LeafSize(e.Kind, e.Size, out bool isLeaf)) { c.Fail("layout_size_mismatch"); return 0; }
                    if (isLeaf)
                    {
                        if (e.Children != 0) { c.Fail("layout_kind_invalid"); return 0; }
                        return at - i;
                    }
                    switch (e.Kind)
                    {
                        case 13: // table
                            if ((ulong)e.Size != sum) { c.Fail("layout_size_mismatch"); return 0; }
                            break;
                        case 35: // optional
                            if (e.Children != 1) { c.Fail("layout_kind_invalid"); return 0; }
                            if ((ulong)e.Size != sum + 1) { c.Fail("layout_size_mismatch"); return 0; }
                            break;
                        case 14: // array
                            if (e.Children != 1) { c.Fail("layout_kind_invalid"); return 0; }
                            if (firstSize == 0) { c.Fail("layout_size_mismatch"); return 0; }
                            bool bare = (e.Size % firstSize) == 0;
                            bool counted = e.Size >= 4 && ((e.Size - 4) % firstSize) == 0;
                            if (!bare && !counted) { c.Fail("layout_size_mismatch"); return 0; }
                            break;
                        case 16: // enum-keyed array
                            if (e.Children != 2) { c.Fail("layout_kind_invalid"); return 0; }
                            if (firstKind != 30) { c.Fail("layout_kind_invalid"); return 0; }
                            if (secondSize == 0 || (e.Size % secondSize) != 0) { c.Fail("layout_size_mismatch"); return 0; }
                            if (e.Size / secondSize < firstChildren) { c.Fail("layout_size_mismatch"); return 0; }
                            break;
                        case 15: // union
                            if (e.Children == 0) { c.Fail("layout_kind_invalid"); return 0; }
                            if (e.Size <= widest) { c.Fail("layout_size_mismatch"); return 0; }
                            if (!OrdinalWidth(e.Size - widest)) { c.Fail("layout_size_mismatch"); return 0; }
                            break;
                        case 30: // enum
                            if (!OrdinalWidth(e.Size)) { c.Fail("layout_size_mismatch"); return 0; }
                            if (e.Children != 0 && !kidsAreVariants) { c.Fail("layout_kind_invalid"); return 0; }
                            break;
                        case 12: // string
                            if (e.Children != 0) { c.Fail("layout_kind_invalid"); return 0; }
                            if (e.Size < 4) { c.Fail("layout_size_mismatch"); return 0; }
                            break;
                        case 33: // wstring
                            if (e.Children != 0) { c.Fail("layout_kind_invalid"); return 0; }
                            if (e.Size < 4 || ((e.Size - 4) % 2) != 0) { c.Fail("layout_size_mismatch"); return 0; }
                            break;
                        default:
                            c.Fail("layout_kind_unknown");
                            return 0;
                    }
                    return at - i;
                }

                public static bool ParseLayout(ReadOnlySpan<byte> bytes, out TableFixedLayoutView view, out string why)
                {
                    view = default;
                    why = null;
                    if (bytes.Length < 4) { why = "layout_malformed"; return false; }
                    uint count = BinaryPrimitives.ReadUInt32LittleEndian(bytes);
                    if (count == 0 || (long)count * EntryBytes + 4 != bytes.Length)
                    {
                        why = "layout_count_mismatch";
                        return false;
                    }
                    view.Bytes = bytes;
                    view.Count = (int)count;
                    TableFixedLayoutEntry root = EntryAt(view, 0);
                    if (root.Kind != 13)
                    {
                        why = "layout_kind_invalid";
                        view = default;
                        return false;
                    }
                    if (root.Size == 0 || root.Size > RecordMaxBytes)
                    {
                        why = "layout_record_too_large";
                        view = default;
                        return false;
                    }
                    Checker c = new Checker { Layout = view, Why = "layout_malformed", Bad = false };
                    int used = CheckEntry(ref c, 0, 0);
                    if (c.Bad)
                    {
                        why = c.Why;
                        view = default;
                        return false;
                    }
                    if (used != view.Count)
                    {
                        why = "layout_tree_unclosed";
                        view = default;
                        return false;
                    }
                    return true;
                }

                public static bool ParseLayout(ReadOnlySpan<byte> bytes, out TableFixedLayoutView view) => ParseLayout(bytes, out view, out _);

                private ref struct Compiler
                {
                    public Span<TableFixedEntry> Plan;
                    public int Capacity;
                    public int Count;
                    public int Pool;
                    public bool Overflow;
                    public TableReport Report;
                    public byte ArgW; // the CURRENT union's tag width, stamped onto every guarded push

                    public void Push(in TableFixedEntry e)
                    {
                        TableFixedEntry stamped = e;
                        if (stamped.Guard != NoGuard)
                        {
                            stamped.ArgW = ArgW == 0 ? (byte)1 : ArgW;
                        }
                        int entrySize = System.Runtime.CompilerServices.Unsafe.SizeOf<TableFixedEntry>();
                        int room = Capacity - (Pool + entrySize - 1) / entrySize;
                        if (Count >= room) { Overflow = true; return; }
                        Plan[Count++] = stamped;
                    }

                    public uint LayTable(ReadOnlySpan<ushort> values, int n)
                    {
                        int bytes = (n + 1) * 2;
                        int entrySize = System.Runtime.CompilerServices.Unsafe.SizeOf<TableFixedEntry>();
                        int total = entrySize * Capacity;
                        Pool += bytes;
                        if (total - Pool < Count * entrySize) { Overflow = true; return 0; }
                        uint at = (uint)(total - Pool);
                        Span<byte> planBytes = MemoryMarshal.AsBytes(Plan);
                        BinaryPrimitives.WriteUInt16LittleEndian(planBytes.Slice((int)at), (ushort)n);
                        for (int i = 0; i < n; ++i)
                        {
                            BinaryPrimitives.WriteUInt16LittleEndian(planBytes.Slice((int)at + 2 + 2 * i), values[i]);
                        }
                        return at;
                    }
                }

                private static void MatchChildren(
                    ref Compiler c,
                    TableFixedLayoutView theirs, int ti, uint their_at,
                    TableFixedLayoutView mine, int mi, ReadOnlySpan<TableFixedDst> dst, uint my_at,
                    uint guard, byte arg)
                {
                    TableFixedLayoutEntry te = EntryAt(theirs, ti);
                    TableFixedLayoutEntry me = EntryAt(mine, mi);
                    int my_child = mi + 1;
                    for (uint k = 0; k < me.Children; ++k)
                    {
                        TableFixedLayoutEntry mc = EntryAt(mine, my_child);
                        int their_child = ti + 1;
                        uint their_off = their_at;
                        for (uint j = 0; j < te.Children; ++j)
                        {
                            TableFixedLayoutEntry tc = EntryAt(theirs, their_child);
                            if (tc.Id == mc.Id)
                            {
                                CompileEntry(ref c, theirs, their_child, their_off, mine, my_child, dst, my_at, guard, arg);
                                break;
                            }
                            their_off += tc.Size;
                            their_child += Subtree(theirs, their_child);
                        }
                        my_child += Subtree(mine, my_child);
                    }
                    int tc_at = ti + 1;
                    for (uint j = 0; j < te.Children; ++j)
                    {
                        TableFixedLayoutEntry tc = EntryAt(theirs, tc_at);
                        bool named = false;
                        int mc_at = mi + 1;
                        for (uint k = 0; k < me.Children; ++k)
                        {
                            if (EntryAt(mine, mc_at).Id == tc.Id) { named = true; break; }
                            mc_at += Subtree(mine, mc_at);
                        }
                        if (!named && c.Report != null) { c.Report.Unknown++; }
                        tc_at += Subtree(theirs, tc_at);
                    }
                }

                private static void CompileEntry(
                    ref Compiler c,
                    TableFixedLayoutView theirs, int ti, uint their_at,
                    TableFixedLayoutView mine, int mi, ReadOnlySpan<TableFixedDst> dst, uint my_at,
                    uint guard, byte arg)
                {
                    TableFixedLayoutEntry te = EntryAt(theirs, ti);
                    TableFixedLayoutEntry me = EntryAt(mine, mi);
                    TableFixedDst d = dst[mi];
                    uint at = my_at + d.Dst;
                    uint aux_at = my_at + d.Aux;
                    if (te.Kind != me.Kind && me.Kind != 35)
                    {
                        if (Widens(te.Kind, me.Kind))
                        {
                            TableFixedEntry e = new TableFixedEntry(
                                their_at, at, te.Size, 0, guard,
                                (byte)(te.Kind == 10 ? WidenF : Widen),
                                arg, (byte)me.Size, (byte)(SignedKind(te.Kind) ? 1 : 0));
                            c.Push(e);
                            return;
                        }
                        if (c.Report != null) { c.Report.KindMismatch++; }
                        return;
                    }
                    // T INTO ?T (§5.2 EMIT, bill §12.8): the reader wrapped a value the
                    // writer carried bare. The PRESENT byte is a CONSTANT 1 at the
                    // wrapper's AUX lane, constant in its VALUE and still carrying the
                    // row's own guard and ordinal (§5.9 #13) — guarded under a union
                    // arm, unguarded at top level, which is one rule and not two — and
                    // the payload is compiled against the writer's own entry under that
                    // same guard. It is not a kind that moved.
                    if (me.Kind == 35 && te.Kind != 35)
                    {
                        c.Push(new TableFixedEntry(0, aux_at, 1, 1, guard, Const, arg, 0));
                        CompileEntry(ref c, theirs, ti, their_at, mine, mi + 1, dst, my_at, guard, arg);
                        return;
                    }
                    switch (me.Kind)
                    {
                        case 35: // Optional wrapper
                        {
                            TableFixedEntry e = new TableFixedEntry(their_at, aux_at, 1, 0, guard, Copy, arg, 0);
                            c.Push(e);
                            CompileEntry(ref c, theirs, ti + 1, their_at + 1, mine, mi + 1, dst, my_at, guard, arg);
                            break;
                        }
                        case 13: // Nested table
                        {
                            MatchChildren(ref c, theirs, ti, their_at, mine, mi, dst, at, guard, arg);
                            break;
                        }
                        case 14: // Array
                        {
                            if (d.Arg == TextBytes)
                            {
                                uint units = Math.Min(me.Size - 4u, te.Size - 4u);
                                TableFixedEntry e = new TableFixedEntry(
                                    their_at, aux_at, units, at, guard, Text, arg, 0, 0, d.Arg);
                                c.Push(e);
                                break;
                            }
                            TableFixedLayoutEntry tel = EntryAt(theirs, ti + 1);
                            TableFixedLayoutEntry mel = EntryAt(mine, mi + 1);
                            uint head = d.Counted != 0 ? 4u : 0u;
                            uint their_n = tel.Size != 0 ? (te.Size - head) / tel.Size : 0u;
                            uint my_n = mel.Size != 0 ? (me.Size - head) / mel.Size : 0u;
                            uint their_base = their_at + head;
                            if (d.Counted != 0)
                            {
                                TableFixedEntry e = new TableFixedEntry(their_at, aux_at, my_n, 0, guard, Count, arg, 0);
                                c.Push(e);
                            }
                            uint n = Math.Min(their_n, my_n);
                            if (d.Stride == 0)
                            {
                                if (tel.Kind == mel.Kind && tel.Size == mel.Size)
                                {
                                    TableFixedEntry e = new TableFixedEntry(their_base, at, n * mel.Size, 0, guard, Flat, arg, 0);
                                    c.Push(e);
                                    break;
                                }
                                // THE FOLD IS NOT A FOLD ACROSS A WIDENING, and dropping the
                                // run would land the reader's defaults over values the writer
                                // sent (§5.2 EMIT kind 14). One entry, widened element by
                                // element, because the folded destination is one span setter
                                // and has no element-wise slot.
                                bool sameFamily = tel.Kind == mel.Kind || Widens(tel.Kind, mel.Kind);
                                if (sameFamily && tel.Size < mel.Size && mel.Size <= 8)
                                {
                                    byte sign = (byte)(tel.Kind == 10 && mel.Kind == 11 ? 2 : (SignedKind(tel.Kind) && tel.Kind != mel.Kind ? 1 : 0));
                                    c.Push(new TableFixedEntry(their_base, at, n * tel.Size, 0, guard, FlatWiden,
                                                               arg, (byte)mel.Size, sign, (byte)tel.Size));
                                    break;
                                }
                                // A KIND THAT MOVED IS REPORTED, NEVER REINTERPRETED (§5.2).
                                if (c.Report != null) { c.Report.KindMismatch++; }
                                break;
                            }
                            for (uint i = 0; i < n; ++i)
                            {
                                CompileEntry(ref c, theirs, ti + 1, their_base + i * tel.Size,
                                             mine, mi + 1, dst, at + i * d.Stride, guard, arg);
                            }
                            break;
                        }
                        case 16: // Enum-keyed array
                        {
                            TableFixedLayoutEntry tkey = EntryAt(theirs, ti + 1);
                            TableFixedLayoutEntry mkey = EntryAt(mine, mi + 1);
                            int tel = ti + 1 + Subtree(theirs, ti + 1);
                            int mel = mi + 1 + Subtree(mine, mi + 1);
                            TableFixedLayoutEntry tee = EntryAt(theirs, tel);
                            for (uint k = 0; k < mkey.Children; ++k)
                            {
                                ulong key_id = EntryAt(mine, mi + 2 + (int)k).Id;
                                for (uint j = 0; j < tkey.Children; ++j)
                                {
                                    if (EntryAt(theirs, ti + 2 + (int)j).Id != key_id) { continue; }
                                    CompileEntry(ref c, theirs, tel, their_at + j * tee.Size,
                                                 mine, mel, dst, at + k * d.Stride, guard, arg);
                                    break;
                                }
                            }
                            break;
                        }
                        case 15: // Union
                        {
                            uint their_tag = TagBytes(theirs, ti);
                            uint my_tag = TagBytes(mine, mi);
                            byte saved_argw = c.ArgW;
                            c.ArgW = (their_tag >= 1u && their_tag <= 8u) ? (byte)their_tag : (byte)1;
                            // FIRST, UNGUARDED: a const 0 of my_tag bytes into the
                            // reader's tag (§5.2 EMIT kind 15). It is None, and it
                            // STANDS WHEN NO ARM MATCHES: without it a tag naming no arm
                            // this reader holds leaves the PREVIOUS record's arm in the
                            // slot, because the arms' consts are guarded and every
                            // guarded entry's destination counts as landed, so the
                            // prefill does not cover the tag either. The row carries its
                            // OWN guard and ordinal — unguarded at top level, guarded
                            // under an outer arm — which is one rule and not two
                            // (§5.9 #13).
                            c.Push(new TableFixedEntry(their_at, aux_at, my_tag, 0, guard, Const, arg, 0));
                            int my_arm = mi + 1;
                            for (uint k = 0; k < me.Children; ++k)
                            {
                                TableFixedLayoutEntry ma = EntryAt(mine, my_arm);
                                int their_arm = ti + 1;
                                for (uint j = 0; j < te.Children; ++j)
                                {
                                    TableFixedLayoutEntry ta = EntryAt(theirs, their_arm);
                                    if (ta.Id == ma.Id)
                                    {
                                        TableFixedEntry tag = new TableFixedEntry(
                                            their_at, aux_at, my_tag, k + 1, their_at, Const, (byte)(j + 1), 0);
                                        c.Push(tag);
                                        CompileEntry(ref c, theirs, their_arm, their_at + their_tag,
                                                     mine, my_arm, dst, at, their_at, (byte)(j + 1));
                                        break;
                                    }
                                    their_arm += Subtree(theirs, their_arm);
                                }
                                my_arm += Subtree(mine, my_arm);
                            }
                            c.ArgW = saved_argw;
                            break;
                        }
                        case 30: // Enum
                        {
                            // A GROWN ORDINAL WIDTH IS A WIDEN, unsigned, and it counts
                            // widened (§5.2 EMIT kind 30, §5.4). Only a SAME-WIDTH
                            // ordinal takes the remap table.
                            if (te.Size < me.Size)
                            {
                                c.Push(new TableFixedEntry(their_at, at, te.Size, 0, guard, Widen, arg, (byte)me.Size));
                                break;
                            }
                            uint n = Math.Min(te.Children, 255u);
                            ushort[] map = new ushort[n];
                            for (uint j = 0; j < n; ++j)
                            {
                                ulong vid = EntryAt(theirs, ti + 1 + (int)j).Id;
                                ushort landed = 0;
                                for (uint k = 0; k < me.Children; ++k)
                                {
                                    if (EntryAt(mine, mi + 1 + (int)k).Id == vid) { landed = (ushort)(k + 1); break; }
                                }
                                map[(int)j] = landed;
                            }
                            uint aux = c.LayTable(map, (int)n);
                            TableFixedEntry e = new TableFixedEntry(
                                their_at, at, te.Size, aux, guard, Ordinal, arg, (byte)me.Size);
                            c.Push(e);
                            break;
                        }
                        case 12: case 33: // Text / WString
                        {
                            uint units = Math.Min(me.Size - 4u, te.Size - 4u);
                            TableFixedEntry e = new TableFixedEntry(
                                their_at, at, units, aux_at, guard, Text, arg, 0, 0, d.Arg);
                            c.Push(e);
                            break;
                        }
                        default:
                        {
                            if (te.Size == me.Size)
                            {
                                TableFixedEntry e = new TableFixedEntry(their_at, at, me.Size, 0, guard, Copy, arg, 0);
                                c.Push(e);
                            }
                            else if (te.Size < me.Size && me.Size <= 8)
                            {
                                TableFixedEntry e = new TableFixedEntry(their_at, at, te.Size, 0, guard, Widen, arg, (byte)me.Size);
                                c.Push(e);
                            }
                            else if (c.Report != null)
                            {
                                c.Report.KindMismatch++;
                            }
                            break;
                        }
                    }
                }

                public static int Compile(
                    TableFixedLayoutView theirs,
                    ReadOnlySpan<byte> my_layout,
                    ReadOnlySpan<TableFixedDst> dst,
                    Span<TableFixedEntry> plan,
                    TableReport report)
                {
                    if (plan.IsEmpty) { return -1; }
                    if (!ParseLayout(my_layout, out TableFixedLayoutView mine)) { return -1; }
                    Compiler c = new Compiler
                    {
                        Plan = plan,
                        Capacity = plan.Length,
                        Report = report,
                        ArgW = 1
                    };
                    MatchChildren(ref c, theirs, 0, 0, mine, 0, dst, 0, NoGuard, 0);
                    if (c.Overflow) { return -1; }
                    return c.Count;
                }

                // THE PREFILL IS THE SLOTS THE PLAN DOES NOT LAND. Cover is the
                // identity plan's destinations; Fills is that set minus everything
                // this plan writes. A GUARDED ENTRY COUNTS AS LANDING: it is a union
                // arm, and an arm's storage is the arm's. Identity's list is empty —
                // its destinations ARE the cover — and that is the rule's limit case,
                // not an exception: the record loop runs the list it was handed.
                // THE HEADER'S HASH SELECTS A KNOWN LAYOUT, and nothing else does
                // (§5.3 step 5). The FIRST index whose hash matches; -1 for a hash the
                // lineage does not hold, which is layout_newer.
                public static int Select(ReadOnlySpan<TableFixedKnownLayout> known, ulong hash)
                {
                    for (int i = 0; i < known.Length; ++i)
                    {
                        if (known[i].Hash == hash) { return i; }
                    }
                    return -1;
                }

                // ONE PLAN PER LINEAGE ENTRY, compiled from THE LOCK'S layout bytes in
                // the static initializer of the generated type — C#'s own build-time
                // lane, and §5.9 #3's first conforming shape: the bytes came from the
                // lock, the walk happens once per type load, OFF EVERY LOAD PATH, and a
                // plan that will not build is recorded as a refusal NAME on that entry
                // rather than discovered at the first file that needs it. Nothing on
                // the load path compiles, nothing on the load path parses a layout, and
                // the load path cannot fail for want of a plan.
                //
                // The pool grows by construction (§5.9 #4): the buffer is retried at
                // four times the size until the plan fits or the declared cap is
                // reached, and the entry that exceeds it carries plan_too_large BY NAME.
                //
                // AND THIS FUNCTION MUST NOT THROW, WHICH IS THE COST OF RUNNING IN A
                // STATIC INITIALIZER AND IS PARTICULAR TO THIS LEG. A static readonly
                // field initializer runs in the type's static constructor, and an
                // exception out of a static constructor is not the caller's to catch: the
                // CLR wraps it in a TypeInitializationException and POISONS THE TYPE —
                // every later touch of ANY member of the generated table class rethrows
                // the same wrapped exception for the life of the process, including the
                // refusal paths, including Select, including a load of a file whose
                // layout is the reader's own. One bad entry in a lock would take the
                // whole table down, and it would take it down with a name no operator
                // can act on.
                //
                // So EVERY ENTRY IS A LANE WITH ITS OWN REFUSAL and there is no throw on
                // this walk to reach. A lane is constructed and stored BEFORE anything
                // can fail on it; a layout that does not parse sets Why to
                // layout_malformed and the loop continues; a plan that outgrows the cap
                // sets plan_too_large and the loop continues; no array is indexed out of
                // its own length and no input is trusted for a size. The refusal a bad
                // entry earns is read at LOAD time, by the one peer that selects it
                // (§5.9 #8) — which is also why a lock bug here costs exactly the
                // version it broke rather than the type.
                public static TableFixedLineagePlan[] LineagePlans(
                    TableFixedKnownLayout[] known,
                    byte[] my_layout,
                    TableFixedDst[] dst,
                    ulong own)
                {
                    TableFixedLineagePlan[] out_ = new TableFixedLineagePlan[known.Length];
                    for (int i = 0; i < known.Length; ++i)
                    {
                        TableFixedLineagePlan lane = new TableFixedLineagePlan();
                        out_[i] = lane;
                        if (known[i].Hash == own) { continue; }
                        if (!ParseLayout(known[i].Layout, out TableFixedLayoutView parsed, out string why))
                        {
                            // A LINEAGE ENTRY THAT IS NOT A LAYOUT is a bug in the lock
                            // and not a wire event (§5.9 #8): the reader still owes a
                            // name rather than a crash.
                            lane.Why = "layout_malformed";
                            continue;
                        }
                        for (int room = 256; ; room *= 4)
                        {
                            TableFixedEntry[] buffer = new TableFixedEntry[room];
                            TableReport census = new TableReport();
                            int made = Compile(parsed, my_layout, dst, buffer, census);
                            if (made < 0)
                            {
                                if (room >= (1 << 18)) { lane.Why = "plan_too_large"; break; }
                                continue;
                            }
                            lane.Entries = buffer;
                            lane.Count = made;
                            lane.Unknown = census.Unknown;
                            lane.KindMismatch = census.KindMismatch;
                            break;
                        }
                    }
                    return out_;
                }

                public static int Fills(
                    ReadOnlySpan<TableFixedEntry> plan,
                    ReadOnlySpan<TableFixedFill> cover,
                    Span<byte> landed,
                    Span<TableFixedFill> dest)
                {
                    landed.Clear();
                    for (int i = 0; i < plan.Length; ++i)
                    {
                        ref readonly TableFixedEntry p = ref plan[i];
                        if ((uint)p.Dst < (uint)landed.Length) { landed[(int)p.Dst] = 1; }
                        if (p.Op == Text && (uint)p.Aux < (uint)landed.Length) { landed[(int)p.Aux] = 1; }
                    }
                    int n = 0;
                    for (int r = 0; r < cover.Length; ++r)
                    {
                        uint pos = cover[r].Dst;
                        uint hi = pos + cover[r].Size;
                        while (pos < hi)
                        {
                            while (pos < hi && (uint)pos < (uint)landed.Length && landed[(int)pos] != 0) { pos++; }
                            if (pos >= hi) { break; }
                            uint start = pos;
                            while (pos < hi && ((uint)pos >= (uint)landed.Length || landed[(int)pos] == 0)) { pos++; }
                            if (n < dest.Length)
                            {
                                dest[n] = new TableFixedFill(start, pos - start);
                            }
                            n++;
                        }
                    }
                    return n;
                }

                public static void FillRun<T>(
                    ReadOnlySpan<TableFixedFill> fill,
                    ReadOnlySpan<TableFixedSlot<T>> slots,
                    T dst)
                {
                    for (int i = 0; i < fill.Length; ++i)
                    {
                        uint off = fill[i].Dst;
                        uint n = fill[i].Size;
                        for (uint s = 0; s < n; ++s)
                        {
                            uint idx = off + s;
                            if (idx < (uint)slots.Length)
                            {
                                slots[(int)idx].Reset?.Invoke(dst);
                            }
                        }
                    }
                }

                // THE TAG IS COMPARED AT ITS OWN WIDTH. A two- or four-byte tag whose
                // low byte happens to be 1 is not arm 1: it is an ordinal this build
                // has no arm for, and reading only the first byte let 0x0101 run arm
                // 1's entries over a stranger's record. ArgW 0 means 1, >8 clamps to
                // 8. Little-endian, the same widths C#'s packet codec reads a tag at.
                public static ulong TagAt(ReadOnlySpan<byte> src, uint guard, byte argw)
                {
                    int w = argw == 0 ? 1 : (argw > 8 ? 8 : argw);
                    int at = (int)guard;
                    switch (w)
                    {
                        case 1: return src[at];
                        case 2: return BinaryPrimitives.ReadUInt16LittleEndian(src.Slice(at));
                        case 4: return BinaryPrimitives.ReadUInt32LittleEndian(src.Slice(at));
                        case 8: return BinaryPrimitives.ReadUInt64LittleEndian(src.Slice(at));
                        default:
                        {
                            ulong v = 0;
                            for (int i = 0; i < w; ++i)
                            {
                                v |= ((ulong)src[at + i]) << (8 * i);
                            }
                            return v;
                        }
                    }
                }

                // THE WIDEN SCRATCH IS THE CALLER'S, AND IT IS HOISTED OUT OF THE RECORD
                // LOOP. Run is called ONCE PER RECORD, so a new byte[runs * dw] taken
                // inside the FlatWiden case allocated once per widened run per record —
                // a batch of ten thousand records paid ten thousand arrays for the same
                // run. The buffer is handed in ref and grown only when a run needs
                // more than it holds, so a whole batch pays one allocation per run
                // width. It is written in full before it is read: every byte of
                // runs * dw is stored by this case, so nothing from the previous
                // record survives into this one.
                public static void Run<T>(
                    ReadOnlySpan<TableFixedEntry> plan,
                    ReadOnlySpan<TableFixedSlot<T>> slots,
                    ReadOnlySpan<byte> src,
                    T dst,
                    TableReport report,
                    ReadOnlySpan<byte> planBytes,
                    ref byte[] widenScratch)
                {
                    for (int i = 0; i < plan.Length; ++i)
                    {
                        ref readonly TableFixedEntry p = ref plan[i];
                        // an entry belonging to an ARM runs only under its own tag,
                        // compared at ArgW bytes, never as a prefix
                        if (p.Guard != NoGuard && TagAt(src, p.Guard, p.ArgW) != p.Arg) { continue; }
                        switch (p.Op)
                        {
                            case Copy:
                            {
                                if (slots[(int)p.Dst].SetBytes != null)
                                {
                                    slots[(int)p.Dst].SetBytes(dst, src.Slice((int)p.Src, (int)p.Size), (int)p.Size);
                                }
                                else if (slots[(int)p.Dst].SetRawReport != null)
                                {
                                    ulong raw = p.Size switch
                                    {
                                        1 => src[(int)p.Src],
                                        2 => BinaryPrimitives.ReadUInt16LittleEndian(src.Slice((int)p.Src)),
                                        4 => BinaryPrimitives.ReadUInt32LittleEndian(src.Slice((int)p.Src)),
                                        8 => BinaryPrimitives.ReadUInt64LittleEndian(src.Slice((int)p.Src)),
                                        _ => 0UL,
                                    };
                                    slots[(int)p.Dst].SetRawReport(dst, raw, report);
                                }
                                else if (p.Size == 1)
                                {
                                    slots[(int)p.Dst].SetRaw?.Invoke(dst, src[(int)p.Src]);
                                }
                                else if (p.Size == 2)
                                {
                                    slots[(int)p.Dst].SetRaw?.Invoke(dst, BinaryPrimitives.ReadUInt16LittleEndian(src.Slice((int)p.Src)));
                                }
                                else if (p.Size == 4)
                                {
                                    slots[(int)p.Dst].SetRaw?.Invoke(dst, BinaryPrimitives.ReadUInt32LittleEndian(src.Slice((int)p.Src)));
                                }
                                else if (p.Size == 8)
                                {
                                    slots[(int)p.Dst].SetRaw?.Invoke(dst, BinaryPrimitives.ReadUInt64LittleEndian(src.Slice((int)p.Src)));
                                }
                                else if (p.Size == 16)
                                {
                                    ulong lo = BinaryPrimitives.ReadUInt64LittleEndian(src.Slice((int)p.Src));
                                    ulong hi = BinaryPrimitives.ReadUInt64LittleEndian(src.Slice((int)p.Src + 8));
                                    slots[(int)p.Dst].SetWide?.Invoke(dst, new UInt128(hi, lo));
                                }
                                else
                                {
                                    slots[(int)p.Dst].SetBytes?.Invoke(dst, src.Slice((int)p.Src, (int)p.Size), (int)p.Size);
                                }
                                break;
                            }
                            case Flat:
                            {
                                slots[(int)p.Dst].SetBytes?.Invoke(dst, src.Slice((int)p.Src, (int)p.Size), (int)p.Size);
                                break;
                            }
                            case FlatWiden:
                            {
                                int sw = p.Meta == 0 ? 1 : p.Meta;
                                int dw = p.DstSize == 0 ? 1 : p.DstSize;
                                int runs = (int)p.Size / sw;
                                int need = runs * dw;
                                if (widenScratch == null || widenScratch.Length < need)
                                {
                                    widenScratch = new byte[need];
                                }
                                System.Span<byte> wide = widenScratch.AsSpan(0, need);
                                for (int e = 0; e < runs; ++e)
                                {
                                    int at = (int)p.Src + e * sw;
                                    if (p.Sign == 2)
                                    {
                                        double d2 = (double)BinaryPrimitives.ReadSingleLittleEndian(src.Slice(at));
                                        BinaryPrimitives.WriteDoubleLittleEndian(wide.Slice(e * dw), d2);
                                        continue;
                                    }
                                    ulong raw = 0;
                                    if (sw == 1) raw = src[at];
                                    else if (sw == 2) raw = BinaryPrimitives.ReadUInt16LittleEndian(src.Slice(at));
                                    else if (sw == 4) raw = BinaryPrimitives.ReadUInt32LittleEndian(src.Slice(at));
                                    else if (sw == 8) raw = BinaryPrimitives.ReadUInt64LittleEndian(src.Slice(at));
                                    if (p.Sign == 1)
                                    {
                                        int bits = sw * 8;
                                        ulong top = 1UL << (bits - 1);
                                        if ((raw & top) != 0) { raw |= ~((top << 1) - 1UL); }
                                    }
                                    System.Span<byte> cell = wide.Slice(e * dw, dw);
                                    if (dw == 1) cell[0] = (byte)raw;
                                    else if (dw == 2) BinaryPrimitives.WriteUInt16LittleEndian(cell, (ushort)raw);
                                    else if (dw == 4) BinaryPrimitives.WriteUInt32LittleEndian(cell, (uint)raw);
                                    else if (dw == 8) BinaryPrimitives.WriteUInt64LittleEndian(cell, raw);
                                }
                                slots[(int)p.Dst].SetBytes?.Invoke(dst, wide, need);
                                // WIDENED COUNTS ONE PER ELEMENT WIDENED, NOT ONE PER ENTRY.
                                // The C++ reference's EMIT has NO FOLD ACROSS A WIDEN: it
                                // emits one entry per element of a widened array, so its
                                // widened for array_elem_widen is n — 4 on that row's
                                // corpus. §5.4's "once per entry" is therefore once per
                                // ELEMENT there, and the ruling is that a fold across a
                                // widen is not allowed to change the number. This leg DOES
                                // fold the run into one entry, for the one copy loop, so it
                                // adds the run's element count and reports the reference's
                                // figure. A scalar widen is runs == 1 and still counts one.
                                if (report != null) { report.Widened += runs; }
                                break;
                            }
                            case Count:
                            {
                                int v = BinaryPrimitives.ReadInt32LittleEndian(src.Slice((int)p.Src));
                                if (v < 0) { v = 0; if (report != null) report.Clamped++; }
                                else if ((uint)v > p.Size) { v = (int)p.Size; if (report != null) report.Clamped++; }
                                slots[(int)p.Dst].SetRaw?.Invoke(dst, (ulong)(uint)v);
                                break;
                            }
                            case Text:
                            {
                                uint unit = (p.Meta == TextWide) ? 2u : 1u;
                                uint cap = p.Size / unit;
                                int v = BinaryPrimitives.ReadInt32LittleEndian(src.Slice((int)p.Src));
                                if (v < 0) { v = 0; if (report != null) report.Clamped++; }
                                else if ((uint)v > cap) { v = (int)cap; if (report != null) report.Clamped++; }
                                slots[(int)p.Dst].SetRaw?.Invoke(dst, (ulong)(uint)v);
                                ReadOnlySpan<byte> textBytes = src.Slice((int)p.Src + 4, (int)p.Size);
                                if (p.Meta == TextWide)
                                {
                                    slots[(int)p.Aux].SetChars?.Invoke(dst, textBytes, v);
                                }
                                else
                                {
                                    slots[(int)p.Aux].SetBytes?.Invoke(dst, textBytes, v);
                                }
                                break;
                            }
                            case Ordinal:
                            {
                                // A 64-BIT TEMPORARY AND AN EIGHT-BYTE CASE (§5.8 row 7,
                                // §4.5): an ordinal width of 8 is admissible, and read
                                // through a 32-bit temporary with no case for it the raw
                                // value stayed 0 — a silent None where the writer named a
                                // variant.
                                ulong raw = 0;
                                if (p.Size == 1) raw = src[(int)p.Src];
                                else if (p.Size == 2) raw = BinaryPrimitives.ReadUInt16LittleEndian(src.Slice((int)p.Src));
                                else if (p.Size == 4) raw = BinaryPrimitives.ReadUInt32LittleEndian(src.Slice((int)p.Src));
                                else if (p.Size == 8) raw = BinaryPrimitives.ReadUInt64LittleEndian(src.Slice((int)p.Src));
                                uint v = 0;
                                if (!planBytes.IsEmpty && p.Aux < (uint)planBytes.Length)
                                {
                                    ReadOnlySpan<byte> tableBytes = planBytes.Slice((int)p.Aux);
                                    ushort count = BinaryPrimitives.ReadUInt16LittleEndian(tableBytes);
                                    if (raw != 0 && raw <= count)
                                    {
                                        v = BinaryPrimitives.ReadUInt16LittleEndian(tableBytes.Slice(2 * (int)raw));
                                    }
                                    // A FORGED ORDINAL — one past the WRITER's own variant
                                    // count — lands 0 and COUNTS HERE, which is NOT where
                                    // §5.4 and §5.9 #27 put it. The move is OWED and it is
                                    // not a one-line move: a bounds pass over STORAGE cannot
                                    // tell this None from an enum or a union the writer left
                                    // unset, so the count would simply VANISH on the compiled
                                    // path. Either the op lands the RAW ordinal and the pass
                                    // clamps it, or §5.4 names this one exception. Glenn's
                                    // call; until then the number stays where this leg's own
                                    // green fixture asserts it.
                                    if (raw > count && report != null) { report.Clamped++; }
                                }
                                if (slots[(int)p.Dst].SetRaw != null)
                                {
                                    slots[(int)p.Dst].SetRaw(dst, v);
                                }
                                else
                                {
                                    slots[(int)p.Dst].SetRawReport?.Invoke(dst, v, report);
                                }
                                break;
                            }
                            case Widen:
                            {
                                ulong raw = 0;
                                if (p.Size == 1) raw = src[(int)p.Src];
                                else if (p.Size == 2) raw = BinaryPrimitives.ReadUInt16LittleEndian(src.Slice((int)p.Src));
                                else if (p.Size == 4) raw = BinaryPrimitives.ReadUInt32LittleEndian(src.Slice((int)p.Src));
                                else if (p.Size == 8) raw = BinaryPrimitives.ReadUInt64LittleEndian(src.Slice((int)p.Src));
                                if (p.Sign != 0)
                                {
                                    int bits = (int)p.Size * 8;
                                    ulong top = 1UL << (bits - 1);
                                    if ((raw & top) != 0)
                                    {
                                        raw |= ~((top << 1) - 1UL);
                                    }
                                }
                                if (p.DstSize == 16)
                                {
                                    UInt128 w = (p.Sign != 0 && (long)raw < 0) ? unchecked((UInt128)(Int128)(long)raw) : (UInt128)raw;
                                    slots[(int)p.Dst].SetWide?.Invoke(dst, w);
                                }
                                else
                                {
                                    slots[(int)p.Dst].SetRaw?.Invoke(dst, raw);
                                }
                                if (report != null) { report.Widened++; }
                                break;
                            }
                            case WidenF:
                            {
                                float f = BinaryPrimitives.ReadSingleLittleEndian(src.Slice((int)p.Src));
                                double d = (double)f;
                                slots[(int)p.Dst].SetDouble?.Invoke(dst, d);
                                if (report != null) { report.Widened++; }
                                break;
                            }
                            case Const:
                            {
                                if (slots[(int)p.Dst].SetRaw != null)
                                {
                                    slots[(int)p.Dst].SetRaw(dst, p.Aux);
                                }
                                else
                                {
                                    slots[(int)p.Dst].SetRawReport?.Invoke(dst, p.Aux, report);
                                }
                                break;
                            }
                            default: break;
                        }
                    }
                }
            }
