            if (v.PosX != 0 && !ids.Add(0xcb4b37357667310eul)) return false;
            if (v.PosY != 0 && !ids.Add(0xcb4b3835766732c1ul)) return false;
            if (v.PosZ != 0 && !ids.Add(0xcb4b353576672da8ul)) return false;
