            }
            if (v.VelY != 0)
            {
                w.HeaderAt(29, 0x6cede5b6eb60ecb4ul, 4, ref ids);
                w.Fixed((ulong)(long)v.VelY, 4);
            }
            if (v.VelZ != 0)
            {
                w.HeaderAt(31, 0x6cede8b6eb60f1cdul, 4, ref ids);
