            BinaryPrimitives.WriteInt32LittleEndian(b.Slice(4), (int)value.Damage);
            BinaryPrimitives.WriteInt32LittleEndian(b.Slice(8), (int)value.HitKind);
            b.Slice(12)[0] = (byte)(value.Crit ? 1 : 0);
        }

